import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error in your code: {e}')

# Check for required imports (syntax only)
found_requests = False
found_json_error = False

for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'requests' for name in node.names):
        found_requests = True
    if isinstance(node, ast.ImportFrom) and node.module == 'requests.exceptions':
        for name in node.names:
            if name.name == 'JSONDecodeError':
                found_json_error = True

if not found_requests:
    raise AssertionError('Task 1: Missing import requests (check syntax)')
if not found_json_error:
    raise AssertionError('Task 1: Missing import JSONDecodeError from requests.exceptions (check syntax)')

# Check that requests.post is called with json parameter
found_post = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if node.func.attr == 'post':
                # Check if json keyword argument is used
                for kw in node.keywords:
                    if kw.arg == 'json':
                        found_post = True
                        break

if not found_post:
    raise AssertionError('Task 3: Missing requests.post() call with json= parameter')

# Check for try block
has_try = any(isinstance(node, ast.Try) for node in ast.walk(tree))
if not has_try:
    raise AssertionError('Task 4: Missing try block')

# Check for if/else inside try (simplified check)
found_if = False
found_else = False
for node in ast.walk(tree):
    if isinstance(node, ast.If):
        found_if = True
        # Check if this if has an else clause
        if node.orelse:
            found_else = True

if not found_if:
    raise AssertionError('Task 5: Missing if statement')
if not found_else:
    raise AssertionError('Task 6: Missing else clause')

print('TEST_PASSED')
